// Inline the creature SVGs into the build: reads <dir>/<agentId>.svg (made by ~/.openclaw/scripts/make-creatures.py) and writes src/ui/creatures.gen.ts.
// The animation CSS is identical in every file, so it is stored once. Run: node tools/gen-creatures.mjs [dir]   (the generated file is committed; the build never reads the SVG directory)
import { readdirSync, readFileSync, writeFileSync } from 'node:fs';
import { homedir } from 'node:os';
import path from 'node:path';
import { fileURLToPath } from 'node:url';

const dir = process.argv[2] ?? path.join(homedir(), '.openclaw/workspace/avatars/creatures');
const out = path.join(path.dirname(fileURLToPath(import.meta.url)), '..', 'src/ui/creatures.gen.ts');
let style = '';
const items = {};
for (const f of readdirSync(dir).filter((x) => x.endsWith('.svg')).sort()) {
  const svg = readFileSync(path.join(dir, f), 'utf8');
  const m = /^(<svg [^>]*>)\s*<style>([\s\S]*?)<\/style>\s*([\s\S]*?)\s*<\/svg>\s*$/.exec(svg);
  if (!m) throw new Error(`${f}: unexpected shape`);
  if (/<script|on\w+\s*=|href\s*=\s*["']?(?!#)/i.test(svg)) throw new Error(`${f}: scripts or links are not allowed`);
  if (style && style !== m[2]) throw new Error(`${f}: animation CSS differs from the other creatures`);
  style = m[2];
  items[f.replace(/\.svg$/, '')] = [m[1], m[3].replace(/>\s+</g, '><')];
}
const body = `// GENERATED by tools/gen-creatures.mjs from ${dir.replace(homedir(), '~')} (make-creatures.py). Do not edit.
/** The animation CSS shared by every creature (default animation plus the st-active / st-idle / st-needs / st-error looks). */
export const CREATURE_STYLE = ${JSON.stringify(style.trim())};
/** agent id -> [root <svg ...> tag, inner markup]. */
export const CREATURES: Record<string, readonly [string, string]> = ${JSON.stringify(items, null, 1)};
`;
writeFileSync(out, body);
console.log(`${Object.keys(items).length} creatures, ${(body.length / 1024).toFixed(0)} KB -> ${path.relative(process.cwd(), out)}`);
